pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 t) public {
        // Ensure we can send 10 ether
        vm.deal(address(this), 10 ether);
        // Bound timestamp to reasonable values
        t = bound(t, 1, type(uint40).max);
        vm.warp(t);

        // Get pastBlockTime before the call
        uint256 past = c.pastBlockTime();

        // Call fallback with exactly 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        // After a successful call, block.timestamp must be > pastBlockTime
        assertTrue(!success || block.timestamp > past);
    }
}

