pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 blockNumOffset) public {
        // Bound blockNumOffset so we can predict block.number % 15
        uint256 targetBlock = block.number + (blockNumOffset % 15);
        vm.roll(targetBlock);

        uint256 balanceBefore = address(c).balance;
        vm.deal(address(this), 10 ether);

        // Send 10 ether to trigger the fallback
        (bool success, ) = address(c).call{value: 10 ether}("");

        if (success) {
            uint256 balanceAfter = address(c).balance;
            if (targetBlock % 15 == 0) {
                // When block number is multiple of 15, contract sends all balance to msg.sender
                assertTrue(balanceAfter == 0);
            } else {
                // Otherwise, balance should increase by 10 ether
                assertTrue(balanceAfter == balanceBefore + 10 ether);
            }
        } else {
            // If reverted, balance unchanged
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

