pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        vm.deal(address(c), 100 ether);
    }

    function testFuzz_property(uint256 blockNumber, uint256 timestamp, bool transferCondition) public {
        // Set block parameters
        vm.roll(blockNumber);
        vm.warp(timestamp);

        // Ensure the call will not revert: timestamp > pastBlockTime (pastBlockTime is 0 initially)
        vm.assume(timestamp > c.pastBlockTime());

        // Record balance before call
        uint256 balanceBefore = address(c).balance;

        // Make the fallback call with exactly 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Only consider successful calls
        if (success) {
            uint256 balanceAfter = address(c).balance;
            // If block.number % 15 == 0, balance should decrease by 10 ether; otherwise unchanged
            bool condition = block.number % 15 == 0;
            if (condition) {
                assertTrue(balanceAfter == balanceBefore - 10 ether, "Balance should decrease by 10 ether when condition met");
            } else {
                assertTrue(balanceAfter == balanceBefore, "Balance should remain unchanged when condition not met");
            }
        }
    }
}

