    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 numCalls) public {
        vm.assume(numCalls > 0 && numCalls < 100);
        uint256 initialBalance = 10 ether;
        vm.deal(address(c), initialBalance);
        uint256 numTransfers = 0;
        uint256 expectedBalance = initialBalance;
        for (uint256 i = 0; i < numCalls; i++) {
            uint256 blockNumBefore = block.number;
            vm.deal(address(this), 10 ether);
            (bool success, ) = address(c).call{value: 10 ether}("");
            require(success);
            if (blockNumBefore % 15 == 0) {
                numTransfers++;
                expectedBalance = expectedBalance < address(c).balance ? expectedBalance : address(c).balance;
                // After transfer, balance becomes 0 plus any subsequent deposits
                expectedBalance = (i + 2) * 10 ether > expectedBalance ? 10 ether : expectedBalance - (expectedBalance / 10 ether) * 10 ether + 10 ether;
            } else {
                expectedBalance += 10 ether;
            }
            // Simulate block progression
            vm.roll(block.number + 1);
            vm.warp(block.timestamp + 1);
        }
        assertTrue(address(c).balance % 10 ether == expectedBalance % 10 ether);
    }
}

